update public.learning_paths
set
  title = 'Philosophy of Language',
  goal = 'Philosophy of Language',
  summary = 'This advanced undergraduate philosophy course studies meaning, reference, truth, speech acts, context, use, language and thought, social meaning, and computational language.',
  data = $plangjson${"slug": "philosophy-of-language", "title": "Philosophy of Language", "description": "This advanced undergraduate philosophy course studies meaning, reference, truth, speech acts, context, use, language and thought, social meaning, and computational language.", "topics": [{"id": "c688a665-e53e-4dd7-ab8b-50fd86ed77c7", "type": "topic", "title": "Analytic Method, Argument, and the Turn to Language", "description": "Students learn why language became central to twentieth- and twenty-first-century philosophy and how to analyze linguistic arguments with precision.", "children": [{"id": "9989bf32-d910-45b1-9fbd-ee29bc192b1f", "type": "subtopic", "title": "The linguistic turn", "children": [{"id": "3b3eba7e-4e7f-4c6c-a192-650780dc356f", "type": "concept", "title": "Frege, Russell, Moore, early analytic philosophy, ordinary language philosophy, and logical positivism"}, {"id": "e545bac0-e8e8-4c4d-b88e-170d06151877", "type": "concept", "title": "Language as a source of philosophical puzzles and as a tool for dissolving them"}, {"id": "1fd774aa-3646-415e-b83c-0f9b007232e4", "type": "concept", "title": "Connections among meaning, truth, reference, mind, logic, and metaphysics"}], "description": "The point is to see why philosophers began treating language as a route into thought, reality, and knowledge."}, {"id": "06bc9b8f-0dc0-49c2-acc9-8af0de692652", "type": "subtopic", "title": "Conceptual analysis", "children": [{"id": "45882417-e7bd-4508-a20a-361883207d2c", "type": "concept", "title": "Definitions, necessary and sufficient conditions, counterexamples, and distinctions"}, {"id": "482ab778-8ec0-45ab-ab09-b1f0b4ef9a42", "type": "concept", "title": "Ambiguity, equivocation, category mistakes, and ordinary-language data"}, {"id": "d9ab96b7-c1de-4355-ba7f-3c277b3cbf75", "type": "concept", "title": "Methodological limits of intuition, usage, formalization, and theory choice"}], "description": "Students learn to clarify terms before trying to solve a philosophical problem."}, {"id": "0f03b251-8297-4446-b1be-df4cb44f73cb", "type": "subtopic", "title": "Argument reconstruction", "children": [{"id": "97fdbd41-ada8-4429-a554-bef09ab68dca", "type": "concept", "title": "Premises, conclusions, hidden assumptions, validity, soundness, and explanatory force"}, {"id": "17c34fea-fdb2-403d-80a6-25be1319f1c6", "type": "concept", "title": "Charitable interpretation, objection mapping, and reply construction"}, {"id": "008ab20f-d75a-483e-a8c4-1a833826088f", "type": "concept", "title": "Short analytic essays, seminar discussion norms, and precision in philosophical writing"}], "description": "The gist is to turn difficult prose into a clear structure that can be evaluated."}]}, {"id": "dec38a96-633d-4592-88b9-00de65212883", "type": "topic", "title": "Sense, Reference, Names, and Descriptions", "description": "This module studies how expressions connect to objects, how names refer, and why descriptions, identity, and informative statements create puzzles.", "children": [{"id": "993ab574-3854-4443-ad18-c773dedc2384", "type": "subtopic", "title": "Fregean sense and reference", "children": [{"id": "e12d7d5b-e6e3-45bf-9614-cbcc84801f0d", "type": "concept", "title": "Cognitive significance, informative identity statements, substitution failure, and opacity"}, {"id": "b321b21f-300e-4e99-9fc7-5b5560668a1c", "type": "concept", "title": "Sense, reference, thought, truth value, and indirect contexts"}, {"id": "8beb1804-aa96-4e61-b415-f5a34c041f4d", "type": "concept", "title": "Morning Star/Evening Star cases and related puzzles of identity"}], "description": "Students learn the classic distinction between what an expression presents and what it refers to."}, {"id": "00459fa6-9ab2-49aa-bc18-fa6ec5b4919b", "type": "subtopic", "title": "Russell on descriptions", "children": [{"id": "8795c84a-f823-4b62-ac2a-5729957fa593", "type": "concept", "title": "Definite descriptions, scope, uniqueness, existence, and logical form"}, {"id": "29506450-b271-4f10-be0f-7bafd53ead91", "type": "concept", "title": "The present king of France, negative existentials, and empty terms"}, {"id": "e5d739c4-7b41-4d4c-8158-e6783804ac9c", "type": "concept", "title": "Descriptions as tools for avoiding misleading surface grammar"}], "description": "The point is to analyze descriptions as quantified structures rather than disguised names."}, {"id": "98b81732-cd8d-4570-8e8c-4f5391621fa9", "type": "subtopic", "title": "Names and direct reference", "children": [{"id": "0f4ca280-2016-4b71-bfe7-a73524b84189", "type": "concept", "title": "Millianism, descriptivism, causal-historical chains, baptism, and speaker communities"}, {"id": "7d16648b-632d-4430-8545-fc93ecc2adae", "type": "concept", "title": "Empty names, fictional names, confused reference, and reference borrowing"}, {"id": "820fe62b-ca2f-4c04-a06d-1b201b578821", "type": "concept", "title": "Problems of cognitive value, belief reports, and substitution"}], "description": "Students compare descriptivist and referential theories of names."}]}, {"id": "e788db74-cad8-4225-8db1-be14a9229384", "type": "topic", "title": "Truth, Propositions, and Truth-Conditional Semantics", "description": "Students examine the idea that knowing meaning involves knowing truth conditions, propositions, logical form, and compositional structure.", "children": [{"id": "1888c5bd-2460-4a73-91fb-b22ee94cd96d", "type": "subtopic", "title": "Truth and meaning", "children": [{"id": "f8a1c2d1-5901-4efe-9da9-6623b5448d9f", "type": "concept", "title": "Truth conditions, propositions, possible circumstances, and semantic content"}, {"id": "1ec784a4-84b5-4b07-8022-f0a460983a14", "type": "concept", "title": "Tarski, Davidson, compositional truth theories, and interpretation"}, {"id": "338b313d-f8d5-42de-ba1b-c9c99ba3ba74", "type": "concept", "title": "Truth, assertion, verification, use, and communication as competing emphases"}], "description": "Students study the idea that sentence meaning is tied to conditions under which a sentence is true."}, {"id": "ce793b43-7f71-48a7-b106-9a23f3b14fc9", "type": "subtopic", "title": "Propositions and content", "children": [{"id": "f55f94c3-a651-4a93-ba6a-dd10ae9f9a30", "type": "concept", "title": "Structured propositions, possible-world propositions, Russellian contents, and Fregean thoughts"}, {"id": "650f3ce3-9d9d-4c9e-b521-2d2393096157", "type": "concept", "title": "Coarse-grained versus fine-grained content and hyperintensional distinctions"}, {"id": "78b34ca2-f79d-4573-96e9-550f1dfbaa6d", "type": "concept", "title": "Belief reports, attitude ascriptions, and cognitive significance"}], "description": "The gist is to ask what is shared by synonymous sentences, beliefs, assertions, and translations."}, {"id": "9bf023db-0756-47b3-b1da-f144d196ae1d", "type": "subtopic", "title": "Compositionality", "children": [{"id": "96a9bf0a-ab5d-4898-b3c7-9b194816d35a", "type": "concept", "title": "Lexical meaning, syntactic structure, functional application, and semantic values"}, {"id": "676837d3-1197-4dee-88a3-0c3ba5764642", "type": "concept", "title": "Scope ambiguity, binding, anaphora, modifiers, and quantifier interaction"}, {"id": "3557d21a-e2fe-49f4-b793-2a27bfba24a4", "type": "concept", "title": "Limits from idioms, context sensitivity, metaphor, and pragmatic enrichment"}], "description": "Students learn why complex meanings depend systematically on parts and structure."}]}, {"id": "cbd4c9db-0c73-4966-ba49-fac15a3d1227", "type": "topic", "title": "Meaning, Use, Rules, and Language Games", "description": "This topic follows Wittgenstein and later pragmatist themes by asking whether meaning is grounded in use, public practice, and rule-governed activity.", "children": [{"id": "7fd43d10-70d5-4a6f-a8cf-be0eb5fae480", "type": "subtopic", "title": "Wittgenstein and use", "children": [{"id": "93990ae2-e7c3-4274-bfa7-3b9b18ced906", "type": "concept", "title": "Meaning as use, language games, forms of life, family resemblance, and grammar"}, {"id": "53ef7b90-c688-490c-be68-4e3716c77071", "type": "concept", "title": "Private language argument, rule following, ostensive definition, and public criteria"}, {"id": "d29960c8-b9a6-4bc5-b33b-b6865b2bf3e5", "type": "concept", "title": "Philosophical therapy, ordinary use, and resistance to essential definitions"}], "description": "Students learn the later Wittgensteinian challenge to overly abstract theories of meaning."}, {"id": "d0feae63-96f2-41d2-a28b-9a19b79c226c", "type": "subtopic", "title": "Rules and practices", "children": [{"id": "a3ce0f9a-f486-4261-b44d-a5507123cbf0", "type": "concept", "title": "Rule following, normativity, correction, agreement, training, and shared practice"}, {"id": "dd5aa3e1-fff8-49fe-8611-948d4a981eee", "type": "concept", "title": "Semantic normativity, communal standards, and individual understanding"}, {"id": "996814ff-dd89-4da7-bfe1-58a758ae55ec", "type": "concept", "title": "Skeptical problems about rules and responses from practice-based accounts"}], "description": "The point is to understand language as a social practice governed by norms."}, {"id": "de3ea2c0-5c52-45aa-947b-6b28f19d17d5", "type": "subtopic", "title": "Ordinary language analysis", "children": [{"id": "d3a2ce82-689f-4403-a003-8586b56d35ed", "type": "concept", "title": "Austin, Strawson, Ryle, ordinary distinctions, and misuse of philosophical abstraction"}, {"id": "556195bf-9b4b-4cf9-a300-49146a44261c", "type": "concept", "title": "Excuses, performatives, categories, and context-sensitive criteria"}, {"id": "d766ee79-4cd2-4f2a-b264-6a9dca875894", "type": "concept", "title": "Strengths and limits of ordinary language evidence"}], "description": "Students see how everyday usage can illuminate or complicate philosophical theory."}]}, {"id": "5ccbb31c-e14f-43e3-8d9e-f8e2d88ee851", "type": "topic", "title": "Speaker Meaning, Intention, Communication, and Interpretation", "description": "Students study how utterances mean what speakers intend, how hearers infer meaning, and how communication succeeds or fails.", "children": [{"id": "43f822c4-ce66-4438-baf7-b5763541d3ea", "type": "subtopic", "title": "Gricean speaker meaning", "children": [{"id": "c768bae8-2e8b-4496-8e38-4f29b08a6273", "type": "concept", "title": "Natural meaning versus nonnatural meaning, audience recognition, and reflexive intentions"}, {"id": "a9e93d3d-f776-4b6c-a7f2-2bbcb0c02fcc", "type": "concept", "title": "Utterer meaning, sentence meaning, conventional meaning, and what is said"}, {"id": "2075fb24-8a7a-4815-b825-92cdb1ed595e", "type": "concept", "title": "Communication without code, inference, and intention recognition"}], "description": "Students learn how meaning can be analyzed through communicative intentions."}, {"id": "ee673901-46f6-4585-99e2-294e1a455ceb", "type": "subtopic", "title": "Interpretation", "children": [{"id": "bb319179-0e61-434e-a93c-c3ff7eb34d58", "type": "concept", "title": "Charity, context, background knowledge, salience, relevance, and common ground"}, {"id": "0b15e3be-d37f-46b9-8ba6-e6b81902f57f", "type": "concept", "title": "Indeterminacy, translation, radical interpretation, and Davidsonian themes"}, {"id": "4f13d8fe-2b46-45ef-9a45-9e627a68e673", "type": "concept", "title": "Miscommunication, ambiguity resolution, repair, and hermeneutic sensitivity"}], "description": "The gist is to ask how hearers recover meaning from incomplete evidence."}, {"id": "c7ff8cc6-2747-4f61-8ea3-d418bcfcdc7b", "type": "subtopic", "title": "Communication models", "children": [{"id": "8339cf8a-afc7-4935-8a88-0030649b8380", "type": "concept", "title": "Symbolic action, sender/receiver models, dialogic models, semiotic approaches, and meaning-making"}, {"id": "09d2d6f9-de5c-4ae3-b6c9-a1afd6aa85c5", "type": "concept", "title": "Audience reception, framing, priming, discourse communities, and public communication"}, {"id": "8c763a0e-8563-4fba-9733-566fd1a6d080", "type": "concept", "title": "Power, ideology, identity, and interpretation in communicative settings"}], "description": "Students connect philosophy of language with communication theory."}]}, {"id": "8f3d0f32-70c3-47ef-88fe-55c6a410f445", "type": "topic", "title": "Speech Acts, Performatives, and Norms of Conversation", "description": "This module treats language as action: promising, ordering, asserting, apologizing, naming, testifying, and changing social reality.", "children": [{"id": "d07d664a-f917-46f8-b28c-7134779a586a", "type": "subtopic", "title": "Speech act taxonomy", "children": [{"id": "81a47508-6835-4a7a-8159-cc70b6c28145", "type": "concept", "title": "Locutionary, illocutionary, and perlocutionary acts"}, {"id": "1255bf41-3a91-426f-bd71-244e234de2e8", "type": "concept", "title": "Assertions, questions, directives, promises, declarations, apologies, and verdictives"}, {"id": "d8643052-d53b-4b54-9d53-f076ff8f6513", "type": "concept", "title": "Felicity conditions, uptake, authority, conventions, and institutional context"}], "description": "Students learn that utterances do things, not merely describe things."}, {"id": "51eb25f9-b1c7-4729-84d1-05745790895d", "type": "subtopic", "title": "Assertion and normativity", "children": [{"id": "e4216b4a-1dc3-4f57-ab6e-bffa9bf599b9", "type": "concept", "title": "Knowledge norm, truth norm, justification norm, sincerity, and responsibility"}, {"id": "ee0d9fff-30d2-4155-bdd4-e90a24fcc4c6", "type": "concept", "title": "Testimony, disagreement, retraction, correction, and public record"}, {"id": "e95f9d62-553f-489b-a19f-9d42e12b44cd", "type": "concept", "title": "Assertion in science, law, journalism, and online discourse"}], "description": "The point is to study assertion as a rule-governed act with epistemic and social consequences."}, {"id": "8b2cdd8f-7c9e-4b16-bf96-6a8b6adcc411", "type": "subtopic", "title": "Performativity and social reality", "children": [{"id": "244df647-2929-4e9b-a462-162900d77d9c", "type": "concept", "title": "Naming, marrying, sentencing, authorizing, declaring, promising, and contracting"}, {"id": "2ca1444c-7427-4cec-9ca9-954aedd43ec3", "type": "concept", "title": "Authority, uptake, misfires, silencing, refusal, and contested speech acts"}, {"id": "ebe9db5f-5a7f-4b50-a6de-3a5b15a2b72e", "type": "concept", "title": "Gender, race, law, ritual, institutions, and social construction"}], "description": "Students examine how words create obligations, identities, statuses, and institutions."}]}, {"id": "237c10a8-0890-4fc7-8022-2a42a9b90006", "type": "topic", "title": "Pragmatics, Implicature, Presupposition, and Context", "description": "Students learn how speakers communicate more than sentence meaning through context, shared assumptions, cooperative norms, and conversational inference.", "children": [{"id": "e565f6a4-391b-4f72-90dc-756118c936f1", "type": "subtopic", "title": "Conversational implicature", "children": [{"id": "42486393-eb39-4fdb-8bbf-d73bc8522820", "type": "concept", "title": "Cooperative principle, maxims, quantity, quality, relation, and manner"}, {"id": "f81c09ef-6809-4b8e-998c-086db9aad691", "type": "concept", "title": "Scalar implicature, generalized implicature, particularized implicature, and cancellation"}, {"id": "d2e4aa3e-d4d5-48f7-b789-0a2bddbbf1f6", "type": "concept", "title": "Irony, understatement, indirectness, and strategic communication"}], "description": "Students learn how speakers imply what they do not explicitly say."}, {"id": "ad958fe4-d088-4765-ae24-6e92798e672f", "type": "subtopic", "title": "Presupposition and common ground", "children": [{"id": "7328f2bc-2878-4519-9e2e-9a52e92946c2", "type": "concept", "title": "Presupposition triggers, projection, accommodation, and conversational scoreboard"}, {"id": "3f910f51-6d41-466c-b039-db8ecf5cd3a7", "type": "concept", "title": "Definite descriptions, factive verbs, change-of-state verbs, and clefts"}, {"id": "29cebd53-786c-43c1-8d94-9b319765f8fc", "type": "concept", "title": "Manipulation, loaded questions, ideology, and contested common ground"}], "description": "The gist is to identify background commitments carried by utterances."}, {"id": "6b012d4f-900e-43f3-a9b9-094b650e1024", "type": "subtopic", "title": "Context and pragmatic enrichment", "children": [{"id": "d0ad29d2-b002-4ef6-b74b-6416d1dae9ef", "type": "concept", "title": "What is said, impliciture, explicature, saturation, free enrichment, and relevance theory"}, {"id": "f3d053b8-1bb9-4bc0-aa09-7c30d07fc1a8", "type": "concept", "title": "Contextualism, minimalism, occasion sensitivity, and pragmatic intrusion"}, {"id": "2eee7726-39f9-445e-ac1c-143634f0c888", "type": "concept", "title": "Legal interpretation, testimony, translation, and AI dialogue as test cases"}], "description": "Students analyze the boundary between semantics and pragmatics."}]}, {"id": "7da3c2c5-e652-40ef-a66b-444190492a4a", "type": "topic", "title": "Indexicals, Demonstratives, Context Sensitivity, and Perspective", "description": "This topic examines expressions whose content shifts with speaker, time, place, salience, and perspective.", "children": [{"id": "3d9df51d-1264-4803-a951-d9b2f2e7d884", "type": "subtopic", "title": "Indexicals and character", "children": [{"id": "74705276-6760-4235-981c-e2b0f70c46cd", "type": "concept", "title": "Kaplanian character and content, context of utterance, circumstance of evaluation"}, {"id": "634775dd-364b-45f3-a7e9-5b0abfeec46e", "type": "concept", "title": "Pure indexicals, demonstratives, temporal expressions, and deictic coordination"}, {"id": "22948424-93b0-4197-bafb-b4efcfd5a48b", "type": "concept", "title": "Direct reference, cognitive significance, and shifted contexts"}], "description": "Students learn how words such as I, here, now, and today depend on context."}, {"id": "a11bdab3-03f5-4922-88b6-7b4bca06fee7", "type": "subtopic", "title": "Demonstratives and salience", "children": [{"id": "12e24c9c-c7ac-435d-ae76-e096c1eff29f", "type": "concept", "title": "Pointing, perception, speaker intention, conventions, and salience"}, {"id": "b8ec85e2-3ddd-4a9c-a361-96350aa8c474", "type": "concept", "title": "Deferred reference, complex demonstratives, anaphora, and visual context"}, {"id": "b373a48a-f117-4950-b80d-dca308bf4594", "type": "concept", "title": "Reference failure, disagreement, and communicative repair"}], "description": "The point is to study how reference depends on attention, intention, and shared situation."}, {"id": "87cf05da-37c6-44b0-b927-1b7ef34bf047", "type": "subtopic", "title": "Perspective and assessment", "children": [{"id": "bbde854b-d486-4f56-90be-b0d6fe41324c", "type": "concept", "title": "Taste predicates, epistemic modals, gradable adjectives, and predicates of personal taste"}, {"id": "10a428bf-f5ec-4c8a-9bb2-3dc8bcb34cde", "type": "concept", "title": "Relativism, contextualism, assessment sensitivity, and disagreement"}, {"id": "e7e52bc5-36cd-45e9-bda3-e2385dd7d92a", "type": "concept", "title": "First-person thought, self-location, centered worlds, and perspective in communication"}], "description": "Students consider expressions whose truth or content may depend on perspective."}]}, {"id": "b6d36665-ddfb-4f89-9582-7b62a643f850", "type": "topic", "title": "Modality, Necessity, Rigid Designation, and Natural Kinds", "description": "Students study Kripkean themes about names, necessity, possible worlds, essences, and scientific kinds.", "children": [{"id": "34d18208-fcd9-4a08-ae6d-63547e98f03e", "type": "subtopic", "title": "Naming and necessity", "children": [{"id": "8f275716-13c5-4424-b805-ee207559e153", "type": "concept", "title": "Rigid designation, possible worlds, transworld identity, and modal intuitions"}, {"id": "ea061c7e-f4b3-460e-a2d8-4c3e211b4287", "type": "concept", "title": "Baptism, causal chains, reference preservation, and speaker communities"}, {"id": "6ea2b252-07ea-449c-bb84-648366f32fb1", "type": "concept", "title": "Hesperus/Phosphorus, Aristotle, Nixon, and identity across worlds"}], "description": "Students study Kripke's challenge to descriptivism and his account of necessary a posteriori truths."}, {"id": "ca0f12e6-62b3-4beb-8905-d428e80028e1", "type": "subtopic", "title": "Natural kind terms", "children": [{"id": "0ad5021a-40b1-4d85-9bad-377659174618", "type": "concept", "title": "Putnam, Twin Earth, semantic externalism, division of linguistic labor, and essences"}, {"id": "21465d07-dde8-4c12-8f9d-53831982ebed", "type": "concept", "title": "Scientific discovery, microstructure, kind membership, and reference revision"}, {"id": "e569bd12-412a-44a9-a120-aa95494a0ed4", "type": "concept", "title": "Natural kinds in chemistry, biology, social kinds, race, gender, and disease categories"}], "description": "The gist is to ask how terms such as water, gold, and tiger refer."}, {"id": "65fdc510-943e-46a9-8636-e605dc7daa4f", "type": "subtopic", "title": "Metaphysical consequences", "children": [{"id": "b67d975b-ae14-487a-85dc-3375ae27c771", "type": "concept", "title": "A priori/a posteriori, necessary/contingent, analytic/synthetic distinctions"}, {"id": "3d88cd8b-3328-4296-abe8-710ccfccd6fe", "type": "concept", "title": "Two-dimensional semantics, conceivability, intensions, and modal epistemology"}, {"id": "45aef83e-576f-4cf9-8a7f-ae307bb77551", "type": "concept", "title": "Ontological commitment, identity, possible worlds, and philosophy of mind implications"}], "description": "Students connect language to necessity, essence, and ontology."}]}, {"id": "9333bdf2-469b-4de2-8bb1-38b7d941e6e8", "type": "topic", "title": "Metaphor, Figurative Language, Vagueness, and Ambiguity", "description": "This module explores nonliteral, flexible, and indeterminate meaning as a serious test of semantic and pragmatic theory.", "children": [{"id": "24edfb67-5cef-4cc9-84aa-bb1c098c12d5", "type": "subtopic", "title": "Metaphor and figurative meaning", "children": [{"id": "6ce9ad9f-7cb4-4d7c-8e21-3bef5a13529f", "type": "concept", "title": "Comparison, interaction, pragmatic, cognitive, and Davidsonian theories of metaphor"}, {"id": "b03d18b5-3624-4905-b6b3-798796ab0b6d", "type": "concept", "title": "Dead metaphors, live metaphors, poetic meaning, framing, and conceptual metaphor"}, {"id": "0315a68e-60ae-4eaa-99c3-a1fabb8d812f", "type": "concept", "title": "Metaphor in science, politics, ethics, and everyday reasoning"}], "description": "Students explore how nonliteral language conveys understanding."}, {"id": "5d0b90e2-a48f-458d-985f-f799dec03937", "type": "subtopic", "title": "Vagueness", "children": [{"id": "4f046752-2923-4ed4-b65e-369f9c6462af", "type": "concept", "title": "Vague predicates, tolerance, sharp boundaries, higher-order vagueness, and borderline cases"}, {"id": "4af447d4-22f1-4fb9-bb95-a9048cd6a75d", "type": "concept", "title": "Supervaluationism, epistemicism, many-valued logic, contextualism, and pragmatic approaches"}, {"id": "6a7bc6a1-d24b-40b9-bf85-10d682d2fd58", "type": "concept", "title": "Legal standards, disease categories, social identity, and policy thresholds"}], "description": "The point is to analyze borderline cases and the sorites paradox."}, {"id": "90095f39-b8b8-4a6f-ac34-4fa888ab57ae", "type": "subtopic", "title": "Ambiguity and polysemy", "children": [{"id": "db0504d1-47e8-4f5d-a3c9-59d7383a7cef", "type": "concept", "title": "Lexical ambiguity, structural ambiguity, scope ambiguity, polysemy, and coercion"}, {"id": "dd40aa68-5d16-48ba-b13d-d485db0d6542", "type": "concept", "title": "Disambiguation, semantic underspecification, context, and corpus evidence"}, {"id": "d3e94cd9-bf47-4a31-ba8d-c39cb8574e5b", "type": "concept", "title": "Humor, poetry, legal texts, translation, and human-computer communication"}], "description": "Students learn to distinguish multiple meanings from context-driven flexibility."}]}, {"id": "7098e0b5-178f-4f11-b612-ad7ddb74a9d8", "type": "topic", "title": "Language, Thought, Concepts, and Cognitive Representation", "description": "Students connect philosophy of language to philosophy of mind, cognitive psychology, concepts, inner speech, and linguistic relativity.", "children": [{"id": "1a696402-7eef-4ac0-a61f-1edf32c3c5bd", "type": "subtopic", "title": "Language and thought", "children": [{"id": "40f79e37-b19a-4fa0-9544-fcb4706eb9cf", "type": "concept", "title": "Language of thought, conceptual role semantics, inner speech, and mental representation"}, {"id": "dcc11fe6-eaed-4edf-abc1-85f85b7e33d4", "type": "concept", "title": "Linguistic relativity, categorization, color terms, spatial language, and number concepts"}, {"id": "50eef427-d390-4cef-8f03-ee4f91c87e4e", "type": "concept", "title": "Concept acquisition, abstraction, and nonlinguistic cognition"}], "description": "Students examine whether thought depends on language and how language shapes cognition."}, {"id": "a63cdb21-46bd-4a87-80bf-ebfe103439c9", "type": "subtopic", "title": "Concepts and categories", "children": [{"id": "0941cb22-a0bc-48b7-a416-cd4fb558a550", "type": "concept", "title": "Classical concepts, prototypes, exemplars, theory theory, and conceptual atomism"}, {"id": "296d057a-940d-40e7-aea2-16d7b600c721", "type": "concept", "title": "Concept possession, inferential role, lexical competence, and expertise"}, {"id": "5391300e-97a7-49ca-ba5f-0184b9eefaa0", "type": "concept", "title": "Social concepts, natural kinds, stereotypes, and conceptual engineering"}], "description": "The gist is to connect word meaning with mental categorization."}, {"id": "f06829bb-afc9-4840-a152-d82aed2b6d67", "type": "subtopic", "title": "Reading, communication, and cognition", "children": [{"id": "2f77daec-5166-4d76-8861-7eaab7da459c", "type": "concept", "title": "Parsing, lexical access, ambiguity resolution, working memory, and discourse processing"}, {"id": "38dc1d40-f47d-4f52-9e93-00b61d7b1da9", "type": "concept", "title": "Knowledge representation, problem solving, reasoning, and mental models"}, {"id": "1e7e9195-237d-427e-909f-765b4e912d9e", "type": "concept", "title": "Empirical evidence, philosophical interpretation, and limits of armchair method"}], "description": "Students connect philosophy with cognitive psychology and psycholinguistics."}]}, {"id": "35e27033-0ad1-4053-8209-0ca94b371560", "type": "topic", "title": "Formal Semantics, Logic, Quantification, and Compositionality", "description": "This topic builds the formal toolkit for analyzing sentence meaning, quantifier scope, logical consequence, and model-theoretic interpretation.", "children": [{"id": "0ffb29ce-15ed-48d6-990a-c6d5335e7d83", "type": "subtopic", "title": "Formal languages", "children": [{"id": "b2005e80-0a04-4806-a1c0-3bc6072cfb1d", "type": "concept", "title": "Syntax, semantics, object language, metalanguage, interpretation, and models"}, {"id": "25e74558-f21a-4fc5-b01f-d238a9ffb0a4", "type": "concept", "title": "Propositional logic, predicate logic, identity, variables, and formal proof"}, {"id": "e684b72e-f173-4d69-b4b5-e1a0294be829", "type": "concept", "title": "Formalization benefits and distortions when applied to natural language"}], "description": "Students learn how artificial languages clarify semantic structure."}, {"id": "972c8ff7-193e-4e2f-94d4-5e3a9873c8e1", "type": "subtopic", "title": "Quantification and scope", "children": [{"id": "d292897b-cdb2-412e-b8fa-072f30f01e7c", "type": "concept", "title": "Universal and existential quantifiers, uniqueness, restricted quantification, and domain sensitivity"}, {"id": "ca1df86e-ab99-4447-835a-344492c2a75c", "type": "concept", "title": "Scope ambiguity, donkey sentences, anaphora, binding, and pronouns"}, {"id": "80ca661d-807b-49fc-afca-b1ec888d68df", "type": "concept", "title": "Descriptions, negative existentials, generalized quantifiers, and plural quantification"}], "description": "The point is to analyze generality, existence, and logical form."}, {"id": "040faa44-2551-4a59-8eba-33d33ef316a9", "type": "subtopic", "title": "Model-theoretic and possible-world tools", "children": [{"id": "27aecfac-0380-4c88-b725-0627891e2d28", "type": "concept", "title": "Models, assignments, satisfaction, truth in a model, validity, and entailment"}, {"id": "a0ba5117-feb9-460e-ac0f-dd0aeb953b43", "type": "concept", "title": "Intensions, extensions, possible worlds, accessibility, and modal operators"}, {"id": "d3920ef7-d9da-4b09-8172-c380ab8c6327", "type": "concept", "title": "Applications to natural language semantics, modal discourse, and philosophical argument"}], "description": "Students use formal machinery for meaning, modality, and consequence."}]}, {"id": "c02e5b42-8435-4ac8-8a8b-f08b56f3b5ca", "type": "topic", "title": "Linguistics, Sociolinguistics, Social Meaning, and Power", "description": "Students connect philosophical theories to real language structure, variation, social identity, ideology, slurs, and language politics.", "children": [{"id": "7e8e976b-5f24-4c6a-a0a7-2f85e02a0bed", "type": "subtopic", "title": "Linguistic structure", "children": [{"id": "218e3b92-bfdb-4196-8613-dec927a35be4", "type": "concept", "title": "Phonetics, phonology, morphology, syntax, semantics, pragmatics, and discourse"}, {"id": "0c5b8df3-b505-4bce-80ae-915c429acb65", "type": "concept", "title": "Compositional structure, grammatical categories, typology, and cross-linguistic variation"}, {"id": "5dc279b5-559b-4ec7-be4e-6740c0148572", "type": "concept", "title": "Historical change, etymology, world Englishes, and language contact"}], "description": "Students gain enough linguistic grounding to avoid treating language as only isolated sentences."}, {"id": "0cea8909-d8c9-406e-b82f-6113ae34b28c", "type": "subtopic", "title": "Social meaning", "children": [{"id": "1ecacc74-2b1c-4f90-baed-29c9ee7aa83e", "type": "concept", "title": "Dialect, register, code-switching, style, indexicality, stance, and accommodation"}, {"id": "c47ad472-d44f-4b38-8b2d-95973bb9ceac", "type": "concept", "title": "Slurs, pejoratives, reclamation, dog whistles, politeness, and linguistic harm"}, {"id": "ec572695-0ee0-4367-b8ec-b9cb64fdc694", "type": "concept", "title": "Ideology, standard language myths, linguistic discrimination, and epistemic injustice"}], "description": "The gist is to understand how language carries identity, status, norms, and power."}, {"id": "1d25fc78-ed8d-4df1-aed0-7de24847d12d", "type": "subtopic", "title": "Language politics and interpretation", "children": [{"id": "e8146f15-330a-49da-ac39-c37d2753d321", "type": "concept", "title": "Framing, propaganda, euphemism, bureaucratic language, legal interpretation, and media discourse"}, {"id": "60dd7b26-e457-4aa0-b426-659097f6dccf", "type": "concept", "title": "Discourse communities, genre, audience reception, and institutional authority"}, {"id": "6a6fb28f-841a-49da-b166-ab80f275a6a3", "type": "concept", "title": "Conceptual engineering, amelioration, contested concepts, and public philosophy"}], "description": "Students study how meaning is contested in public life."}]}, {"id": "ffed65ee-722d-4874-91b5-101d593d7f92", "type": "topic", "title": "Computational Language, NLP, LLMs, Grounding, and Evaluation", "description": "This module asks what modern language models reveal and fail to reveal about meaning, reference, understanding, and communication.", "children": [{"id": "ec33af9e-b5bf-4f77-92f5-bdb6743e4eee", "type": "subtopic", "title": "NLP as a philosophical test case", "children": [{"id": "b2444df5-b014-48b7-9275-dcc6cc95e277", "type": "concept", "title": "Tokenization, embeddings, language models, parsing, translation, classification, and question answering"}, {"id": "76e32df7-a500-4597-94f5-c50836ee51a6", "type": "concept", "title": "Distributional semantics, vector meaning, compositionality, and statistical prediction"}, {"id": "1a1ad6fb-04c3-4825-a419-a9a953960bba", "type": "concept", "title": "What NLP captures about use patterns and what it may miss about reference, truth, and intention"}], "description": "Students learn how computational models pressure classic accounts of meaning."}, {"id": "0263056f-d0c0-4556-ac3f-f541ae4041f8", "type": "subtopic", "title": "Large language models and understanding", "children": [{"id": "98602aac-8279-4b45-bc29-047db896120a", "type": "concept", "title": "Transformers, attention, pretraining, prompting, instruction tuning, and conversational systems"}, {"id": "025f8d5c-1eb8-4aa8-875e-6ac480a418d8", "type": "concept", "title": "Grounding, symbol manipulation, Chinese Room arguments, intentionality, and semantic competence"}, {"id": "2fc8b702-c03d-4b30-a8e4-cfcbfa75c77b", "type": "concept", "title": "Hallucination, truthfulness, explanation, context windows, and pragmatic alignment"}], "description": "The point is to ask whether fluent language behavior is evidence of meaning or understanding."}, {"id": "32f16e6d-a30e-4a59-b1c4-257ecbe8a55c", "type": "subtopic", "title": "Evaluation and ethics", "children": [{"id": "bf483e9f-afb2-43a5-996f-79b999858e37", "type": "concept", "title": "Benchmarks, annotation, ambiguity, bias, robustness, interpretability, and calibration"}, {"id": "9382c940-ce1a-40cc-be9a-4afd90c07be4", "type": "concept", "title": "Slurs, toxicity, representation, privacy, misinformation, and social harms"}, {"id": "4fe74569-7806-4abb-a6f0-7e6a408e5836", "type": "concept", "title": "Human evaluation, communicative norms, disclosure, accountability, and design choices"}], "description": "Students connect semantic theory to responsible language technology."}]}, {"id": "e4b1526e-c03c-47dd-9406-e5aa07a9afe0", "type": "topic", "title": "Capstone: Seminar Paper on Meaning, Reference, or Communication", "description": "Students synthesize the course by developing a focused philosophical paper with textual evidence, formal or linguistic analysis, objections, and replies.", "children": [{"id": "86b8cd28-51fc-4ff3-9228-30b6688f71e9", "type": "subtopic", "title": "Topic design", "children": [{"id": "18626ea2-5149-4e53-81d8-8b455d1f3369", "type": "concept", "title": "Choose a puzzle: names, descriptions, truth, metaphor, context, slurs, LLMs, or language and thought"}, {"id": "0b6a0164-0412-4350-b8fc-619a875094fb", "type": "concept", "title": "Frame the issue, define terms, identify primary texts, and state stakes"}, {"id": "e2bfb01e-cb05-4745-9a2a-ae766dc7f5d3", "type": "concept", "title": "Build an annotated bibliography using SEP, IEP, PhilPapers, and course readings"}], "description": "Students learn to turn a broad debate into a researchable philosophical question."}, {"id": "fa067979-c1c0-422a-9ce4-c1c5ba713c02", "type": "subtopic", "title": "Argument development", "children": [{"id": "1645b661-5b8a-4ab9-85e7-7639e2b72cf8", "type": "concept", "title": "Reconstruct target arguments, isolate assumptions, and formulate a clear thesis"}, {"id": "26fe9678-a6b6-4dd0-97d0-6789e1592e44", "type": "concept", "title": "Use examples, formal tools, linguistic evidence, or computational cases where appropriate"}, {"id": "f205d4c1-42da-4657-b4d6-3d1fb13a9d17", "type": "concept", "title": "Develop objections, replies, concessions, and principled distinctions"}], "description": "The gist is to defend a thesis against the strongest rival accounts."}, {"id": "c6166650-a43f-4edf-880a-766d1e2ffa2b", "type": "subtopic", "title": "Presentation and revision", "children": [{"id": "3d684985-46af-4ebb-9848-021901bf72c4", "type": "concept", "title": "Conference-style presentation, handout, peer questions, and oral defense"}, {"id": "ae5a7737-d6e1-4f6a-b6a9-d80a8d19f65a", "type": "concept", "title": "Draft workshop, revision memo, citation discipline, and argumentative polish"}, {"id": "dcc3cad6-4e25-41b6-9478-717139a96d6c", "type": "concept", "title": "Final paper, reflection on method, and transfer to future philosophy or language research"}], "description": "Students practice seminar-level philosophical communication."}]}], "dbBacked": true}$plangjson$::jsonb,
